package net.civeira.phylax.features.notification.message.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class UrgentVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property urgent of message ")
  void test_urgent_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> UrgentVO.tryFrom(null));
    Assertions.assertEquals(true, UrgentVO.from(true).isUrgent());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> UrgentVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + true + "]", UrgentVO.from(true).toString());
  }
}
